n30743.content:
\begin{defn}[simplicial set]\label{defn:simplicial-set}
  \lean{SSet}
  \leanok
  \uses{defn:simplex-category}
  A \textbf{simplicial set} is a presheaf on the simplex category.
\end{defn}

n30744.content:
\begin{lemma}[homotopic 1-simplices in a quasi-category]\label{lem:qcat-1-simplex-htpy}
    \uses{defn:1-simplex-htpy, defn:quasi-category}
    Parallel 1-sim\-plices $f$ and $g$ in a quasi-category are homotopic if and only if there exists a 2-simplex of any or equivalently all of the forms displayed in Definition \ref{defn:1-simplex-htpy}.
   \end{lemma}

n30745.content:
\begin{proof}
  \uses{defn:quasi-category} A lengthy exercise in low-dimensional horn filling.
   \end{proof}

n30746.content:
\begin{lem}\label{lem:1-simplex-htpy-in-homotopy-cat}
  \uses{defn:homotopy-cat, defn:1-simplex-htpy}
  Homotopic 1-simplices in a simplicial set represent the same arrow in the homotopy category.
\end{lem}

n30749.content:
\begin{proof}
  \uses{lem:htpy-cat-of-qcat, prop:nerve-reflective, defn:2-truncated-qcat-htpy-cat}
  We have a canonical comparison functor from the homotopy category of the products to the product of the homotopy categories. It follows from Definition \ref{defn:2-truncated-qcat-htpy-cat} and Lemma \ref{lem:htpy-cat-of-qcat} that this is an isomorphism on underlying quivers, which suffices.
\end{proof}

n30750.content:
\begin{definition}[isomorphism in a quasi-category]\label{defn:isomorphism}
    \uses{defn:simplicial-set} A 1-simplex in a quasi-category is an \textbf{isomorphism}\footnote{Joyal refers to these maps as ``isomorphisms'' while Lurie refers to them as ``equivalences.'' We prefer, wherever possible, to use the same term for $\infty$-categorical concepts as for the analogous 1-categorical ones.} just when it represents an isomorphism in the homotopy category. By Lemma \ref{lem:htpy-cat-of-qcat} this means that $f \colon a \to b$ is an isomorphism if and only if there exists a 1-simplex $f^{-1} \colon b \to a$ together with a pair of 2-simplices
   \begin{center}
   \begin{tikzcd}[row sep=small, column sep=small]
   & b \arrow[dr, "f^{-1}", dashed] & & & & a \arrow[dr, "f"] \\ a \arrow[ur, "f"] \arrow[rr, equals] & & a & & b \arrow[ur, "f^{-1}", dashed] \arrow[rr, equals] & & b
   \end{tikzcd}
   \end{center}
   \end{definition}

n30751.content:
\begin{proposition}\label{prop:coherent-iso}
    \uses{defn:isomorphism, defn:quasi-category, defn:coherent-isomorphism}
    An arrow $f$ in a quasi-category $A$ is an isomorphism if and only if it extends to a homotopy coherent isomorphism
   \begin{center}
   \begin{tikzcd} {\Bbbtwo}\arrow[r, "f"] \arrow[d, hook] & A \\ {\BbbI}\arrow[ur, dashed]
   \end{tikzcd}
   \end{center}
   \end{proposition}

n30752.content:
\begin{lemma}\label{lem:qcat-htpy-cat-equiv}
    \uses{defn:qcat-equivalence, defn:homotopy-cat}
    If $f \colon A \to B$ is an equivalence of quasi-categories, then the functor ${\mathord{\mathsf{h}}}{f} \colon {\mathord{\mathsf{h}}}{A} \to {\mathord{\mathsf{h}}}{B}$ is an equivalence of categories, where the data displayed above defines an equivalence inverse ${\mathord{\mathsf{h}}}{g} \colon {\mathord{\mathsf{h}}}{B} \to {\mathord{\mathsf{h}}}{A}$ and natural isomorphisms encoded by the composite\footnote{Note that ${\mathord{\mathsf{h}}}(A^{\BbbI}) \ncong ({\mathord{\mathsf{h}}}{A})^{\BbbI}$ in general. Objects in the latter are homotopy classes of isomorphisms in $A$, while objects in the former are homotopy coherent isomorphisms, given by a specified 1-simplex in $A$, a specified inverse 1-simplex, together with an infinite tower of coherence data indexed by the nondegenerate simplices in ${\BbbI}$.} functors
  \begin{center} \begin{tikzcd} {\mathord{\mathsf{h}}}{A} \arrow[r, "{\mathord{\mathsf{h}}}{\alpha}"] & {\mathord{\mathsf{h}}}(A^{\BbbI}) \arrow[r] & ({\mathord{\mathsf{h}}}{A})^{\BbbI}& {\mathord{\mathsf{h}}}{B} \arrow[r, "{\mathord{\mathsf{h}}}{\beta}"] & {\mathord{\mathsf{h}}}(B^{\BbbI}) \arrow[r] & ({\mathord{\mathsf{h}}}{B})^{\BbbI}\end{tikzcd}
  \end{center}
  \end{lemma}

n30753.content:
\begin{definition}\label{defn:n-arrow}
  \uses{defn:simplicial-category, defn:simplicial-set}
For each $n \geq 0$, an $n$-simplex in ${\mathord{\mathcal{A}}}(x,y)$ is referred to as an $n$-\textbf{arrow} from $x$ to $y$.
\end{definition}

n30754.content:
\begin{lemma}\label{lem:cat-of-n-arrows} For any simplicial category ${\mathord{\mathcal{A}}}$ and $n \geq 0$,
the $n$-arrows assemble into the arrows of an ordinary category ${\mathord{\mathcal{A}}}_n$ with the same set of objects as ${\mathord{\mathcal{A}}}$.
\end{lemma}

n30755.content:
\begin{proof}
  \uses{defn:n-arrow}
The category of $n$-arrows is easy to construct directly. Alternatively, this result can be proven by applying the theory of change-of-base of \S\ref{sec:change-of-base} to the functor $\textup{ev}_n \colon {\mathord{\mathcal{sSet}}}\to {\mathord{\mathcal{Set}}}$.
\end{proof}

n30756.content:
\begin{lemma}\label{lem:cotensor-associativity}
  \uses{defn:simplicial-cotensors} When a simplicial category has cotensors, cotensors are associative: given $A \in {\mathord{\mathcal{A}}}$ and simplicial sets $U$ and $V$ there are canonical isomorphisms \[ (A^U)^V \cong A^{U \times V} \cong (A^V)^U.\]
\end{lemma}

n30757.content:
\begin{proof}
By the enriched Yoneda lemma, these objects represent the same simplicial functors ${\mathord{\mathcal{A}}}^{\mathord{\textup{op}}}\to {\mathord{\mathcal{sSet}}}$.
\end{proof}

n30758.content:
\begin{definition}\label{defn:equivalence}
  \uses{defn:cosmos, defn:qcat-equivalence}
  In an $\infty$-cosmos ${\mathord{\mathcal{K}}}$, a morphism $f\colon A \to B$ is an \textbf{equivalence} just when the induced map $f_* \colon{\mathord{\mathsf{Fun}}}(X,A) \xrightarrow{{\smash{\mathlower{0.8}{\sim}}}}{\mathord{\mathsf{Fun}}}(X,B)$ on functor spaces  is an equivalence of quasi-categories for all $X \in {\mathord{\mathcal{K}}}$.
\end{definition}

n30759.content:
\begin{definition}\label{defn:trivial-fibration}
  \uses{defn:cosmos, defn:equivalence}
  In an $\infty$-cosmos ${\mathord{\mathcal{K}}}$, a morphism $f\colon A \to B$ is a \textbf{trivial fibration} just when $f$ is both an isofibration and an equivalence.
\end{definition}

n30760.content:
\begin{definition}\label{defn:underlying-cat-of-cosmos}
  \uses{defn:cosmos} The underlying category ${\mathord{\mathcal{K}}}_0$ of an $\infty$-cosmos ${\mathord{\mathcal{K}}}$ is the category whose objects are the $\infty$-categories in ${\mathord{\mathcal{K}}}$ and whose morphisms are the $0$-arrows, i.e., the vertices in the functor spaces.
\end{definition}

n30761.content:
\begin{lemma}[trivial fibrations and conical limits]\label{lem:trivial-fib-conical}
  \uses{defn:cosmos, defn:trivial-fibration}
  The trivial fibrations in an $\infty$-cosmos define a subcategory containing the isomorphisms and are stable under product, pullback, and forming inverse limits of towers.
\end{lemma}

n30763.content:
\begin{lemma}[trivial fibrations and cotensors]\label{lem:trivial-fib-leibniz}
  \uses{defn:cosmos, defn:trivial-fibration}
  In an $\infty$-cosmos, the Leibniz cotensors of any trivial fibration with a monomorphism of simplicial sets is a trivial fibration as is the Leibniz cotensor of an isofibration with a map in the class cellularly generated by the inner horn inclusions and the map ${\Bbbone}\hookrightarrow{\BbbI}$.
\end{lemma}

n30765.content:
\begin{lemma}[representable trivial fibrations]\label{lem:trivial-fib-representability}
  \uses{defn:qcat-trivial-fibration, defn:trivial-fibration}
If $E %
  \mathrel{\ooalign{$\xrightarrow[\mkern4mu]{{\smash{\mathlower{0.8}{\sim}}}\mkern4mu}$\cr%
  \hidewidth$\rightarrow\mkern4mu$}}
B$ is a trivial fibration in an $\infty$-cosmos, then is ${\mathord{\mathsf{Fun}}}(X,E)%
  \mathrel{\ooalign{$\xrightarrow[\mkern4mu]{{\smash{\mathlower{0.8}{\sim}}}\mkern4mu}$\cr%
  \hidewidth$\rightarrow\mkern4mu$}}
{\mathord{\mathsf{Fun}}}(X,B)$ is a trivial fibration of quasi-categories.
\end{lemma}

n30766.content:
\begin{proof}
By axiom \ref{defn:cosmos}\ref{itm:cosmos-isofib} and the definition of the trivial fibrations in an $\infty$-cosmos, we know that if $E %
  \mathrel{\ooalign{$\xrightarrow[\mkern4mu]{{\smash{\mathlower{0.8}{\sim}}}\mkern4mu}$\cr%
  \hidewidth$\rightarrow\mkern4mu$}}
B$ is a trivial fibration then  ${\mathord{\mathsf{Fun}}}(X,E)%
  \mathrel{\ooalign{$\xrightarrow[\mkern4mu]{{\smash{\mathlower{0.8}{\sim}}}\mkern4mu}$\cr%
  \hidewidth$\rightarrow\mkern4mu$}}
{\mathord{\mathsf{Fun}}}(X,B)$ is both an isofibration and an equivalence, and hence is a trivial fibration by the compatibility of these classes in the Joyal model structure.
\end{proof}

n30767.content:
\begin{lemma}[equivalences are homotopy equivalences]\label{lem:equiv-htpy-equiv}
  \uses{defn:cosmos, defn:coherent-isomorphism, defn:equivalence}
A map $f \colon A \to B$ between $\infty$-categories in an $\infty$-cosmos ${\mathord{\mathcal{K}}}$ is an equivalence if and only if it extends to the data of a ``homotopy equivalence'' with the free-living isomorphism ${\BbbI}$ serving as the interval: that is, if there exist maps $g \colon B \to A$
\begin{center}
\begin{tikzcd} & A & &  & B \\ A \arrow[ur, equals] \arrow[dr, "gf"'] \arrow[r, "\alpha"] & A^{\BbbI}\arrow[u, two heads, "\sim", "\textup{ev}_0"'] \arrow[d, two heads, "\sim"',  "\textup{ev}_1"] & \text{and} &  B \arrow[dr, equals] \arrow[r, "\beta"] \arrow[ur, "fg"] & B^{\BbbI}\arrow[u, two heads, "\sim", "\textup{ev}_0"'] \arrow[d, two heads, "\sim"', "\textup{ev}_1"] \\ & A & &  & B
\end{tikzcd}
\end{center}
in the $\infty$-cosmos.
\end{lemma}

n30768.content:
\begin{proof}
By hypothesis, if $f \colon A \to B$ defines an equivalence in the $\infty$-cosmos ${\mathord{\mathcal{K}}}$ then the induced map on post-composition $f_* \colon {\mathord{\mathsf{Fun}}}(B,A) \xrightarrow{{\smash{\mathlower{0.8}{\sim}}}}{\mathord{\mathsf{Fun}}}(B,B)$ is an equivalence of quasi-categories in the sense of Definition \ref{defn:qcat-equivalence}. Evaluating the inverse equivalence $\tilde{g} \colon {\mathord{\mathsf{Fun}}}(B,B) \xrightarrow{{\smash{\mathlower{0.8}{\sim}}}}{\mathord{\mathsf{Fun}}}(B,A)$ and homotopy $\tilde{\beta} \colon {\mathord{\mathsf{Fun}}}(B,B) \to {\mathord{\mathsf{Fun}}}(B,B)^{\BbbI}$ at the 0-arrow $\textup{id}_B \in {\mathord{\mathsf{Fun}}}(B,B)$, we obtain a 0-arrow $g \colon B \to A$ together with an isomorphism $\beta \colon {\BbbI}\to{\mathord{\mathsf{Fun}}}(B,B)$ from the composite $fg$ to $\textup{id}_B$. By the defining universal property of the cotensor \eqref{eq:cotensor-defn}, this isomorphism internalizes to define the map $\beta \colon B \to B^{\BbbI}$ in ${\mathord{\mathcal{K}}}$ displayed on the right of the displayed equation in the statement.

Now the hypothesis that $f$ is an equivalence also provides an equivalence of quasi-categories $f_* \colon {\mathord{\mathsf{Fun}}}(A,A) \xrightarrow{{\smash{\mathlower{0.8}{\sim}}}}{\mathord{\mathsf{Fun}}}(A,B)$, and the map $\beta f \colon A \to B^{\BbbI}$ represents an isomorphism in ${\mathord{\mathsf{Fun}}}(A,B)$ from $fgf$ to $f$. Since $f_*$ is an equivalence, we conclude from Lemma \ref{lem:qcat-htpy-cat-equiv} that $\textup{id}_A$ and $gf$ are isomorphic in the quasi-category ${\mathord{\mathsf{Fun}}}(A,A)$: explicitly, such an isomorphism may be defined by applying the inverse equivalence $\tilde{h} \colon {\mathord{\mathsf{Fun}}}(A,B) \to {\mathord{\mathsf{Fun}}}(A,A)$ and composing with the components at $\textup{id}_A, gf \in {\mathord{\mathsf{Fun}}}(A,A)$ of the isomorphism $\tilde{\alpha} \colon {\mathord{\mathsf{Fun}}}(A,A) \to {\mathord{\mathsf{Fun}}}(A,A)^{\BbbI}$ from $\textup{id}_{{\mathord{\mathsf{Fun}}}(A,A)}$ to $\tilde{h}f_*$. Now by Proposition \ref{prop:coherent-iso} this isomorphism is represented by a map ${\BbbI}\to {\mathord{\mathsf{Fun}}}(A,A)$ from $\textup{id}_A$ to $gf$, which internalizes to a map $\alpha \colon A \to A^{\BbbI}$ in ${\mathord{\mathcal{K}}}$ displayed on the left of the displayed equation in the statement.

The converse is easy: the simplicial cotensor construction commutes with ${\mathord{\mathsf{Fun}}}(X,-)$, so a homotopy equivalence induces a  homotopy equivalence of quasi-categories as in Definition \ref{defn:qcat-equivalence}.
\end{proof}

n30769.content:
\begin{lemma}\label{lem:equivalence-2-of-3}
    \uses{defn:equivalence} The equivalences in an $\infty$-cosmos are closed under retracts and satisfy the \textbf{2-of-3 property}: given a composable pair of functors and their composite, if any two of these are equivalences so is the third.
\end{lemma}

