& & A \arrow[r, "v"'] &C & &A \arrow[r, "f"'] \arrow[ur, "v"'] & B \arrow[r, "t"] & D \\ C \arrow[r, "u"] \arrow[d, "h"'] \arrow[urrr, bend left=40, equals] & A \arrow[d, "f"'] \arrow[r, "\alpha"] \arrow[ur, equals] & A^{\BbbI}\arrow[u,
