Fun(X,B)$ for any $\infty$-category $X$.  By Definition \ref{defn:qcat-trivial-fibration}, we may solve the lifting problem below-left
\begin{center}
\begin{tikzcd} \emptyset=\partial\Delta[0] \arrow[d, hook] \arrow[r] & {\mathord{\mathsf{Fun}}}(B,E) \arrow[d, two heads, "\sim"', "p_*" pos=.4] & {\Bbbone}+{\Bbbone}\arrow[d, hook] \arrow[rr, "{(\textup{id}_E,sp)}"] & & {\mathord{\mathsf{Fun}}}(E,E)  \arrow[d, two heads, "\sim"', "p_*" pos=.4] \\ {\Bbbone}= \Delta[0] \arrow[ur, dashed, "s"] \arrow[ur, dashed] \arrow[r, "\textup{id}_B"'] & {\mathord{\mathsf{Fun}}}(B,B) & {\BbbI}\arrow[r, "!"'] \arrow[urr, dashed, "\alpha"] & {\Bbbone}\arrow[r, "p"'] & {\mathord{\mathsf{Fun}}}(E,B)
\end{tikzcd}
\end{center}
to find a map $s \colon B \to E$ so that $ps = \textup{id}_B$, and then solve the lifting problem above-right to construct the desired fibered homotopy. The converse is immediate from Lemma \ref{lem:equiv-htpy-equiv}.
\end{proof}

n30773.content:
\begin{lemma}[Brown factorization lemma]\label{lem:brown-fact}
  \uses{defn:cosmos, defn:equivalence, defn:trivial-fibration}
  Any functor $f\colon A \to B$ in an $\infty$-cosmos may be factored as an equivalence followed by an isofibration, where this equivalence is constructed as a section of a trivial fibration.
\begin{center}
\begin{tikzcd}
  & Pf \arrow[dr, two heads, "p"] \arrow[dl, two heads, bend right, start anchor=190, end anchor=70, "q"'] & \\ A \arrow[rr, "f"'] \arrow[ur, bend right=25, start anchor=30, end anchor=230, "\sim", "s"' pos = 0.6] & & B
\end{tikzcd}
\end{center}
Moreover, $f$ is an equivalence if and only if the isofibration $p$ is a trivial fibration.
\end{lemma}

n30774.content:
\begin{proof}
The displayed factorization is constructed by the pullback of an isofibration formed by the simplicial cotensor of the inclusion ${\Bbbone}+{\Bbbone}\hookrightarrow{\BbbI}$ into the $\infty$-category $B$.
\begin{center}
\begin{tikzcd}
& A^{\BbbI}\arrow[dr, "f^{\BbbI}"] & \\
A \arrow[r, "\sim", "s"'] \arrow[ur, "\Delta"] \arrow[dr, "{(A,f)}"'] &  Pf \arrow[r] \arrow[d, two heads, "{(q,p)}"' pos=.4] \arrow[dr, phantom, "\lrcorner" very near start] & B^{\BbbI}\arrow[d, two heads, "{(\textup{ev}_0,\textup{ev}_1)}"] \\  & A \times B \arrow[r, "f \times B"'] & B \times B
\end{tikzcd}
\end{center}
Note the map $q$ is a pullback of the trivial fibration $\textup{ev}_0 \colon B^{\BbbI}%
  \mathrel{\ooalign{$\xrightarrow[\mkern4mu]{{\smash{\mathlower{0.8}{\sim}}}\mkern4mu}$\cr%
  \hidewidth$\rightarrow\mkern4mu$}}
B$ and is hence a trivial fibration. Its section $s$, constructed by applying the universal property of the pullback to the displayed cone with summit $A$, is thus an equivalence by the 2-of-3 property. Again by 2-of-3, it follows that $f$ is an equivalence if and only if $p$ is.
\end{proof}

n30775.content:
\begin{proposition}\label{prop:change-of-base-adjunction}
  \uses{defn:lax-monoidal-functor, prop:change-of-base}
  Any adjunction between cartesian closed categories whose left adjoint preserves finite products induces a change-of-base 2-adjunction
\begin{center}
\begin{tikzcd}[column sep=large]
{\mathord{\mathcal{V}}}\arrow[r, bend left=20, "F"] \arrow[r, phantom, "\bot"] & {\mathord{\mathcal{W}}}\arrow[l, bend left=20, "U"] \arrow[r, phantom, "\rightsquigarrow"] & {{\mathord{\mathcal{V}}}}\text{-}\mathcal{C}at \arrow[r, bend left=20, start anchor=10, end anchor=170,  "F_*"] \arrow[r, phantom, "\bot"] & {{\mathord{\mathcal{W}}}}\text{-}\mathcal{C}at \arrow[l, bend left=20, start anchor=190, end anchor=-10,  "U_*"]
\end{tikzcd}
\end{center}
\end{proposition}

n30777.content:
\begin{corollary}\label{cor:free-underlying-2-adj}
  \uses{prop:change-of-base-adjunction}
 For any cartesian closed category ${\mathord{\mathcal{V}}}$ with coproducts, the underlying category construction and free category construction define  adjoint 2-functors
\begin{center}
\begin{tikzcd}[column sep=large]
  \mathcal{C}at \arrow[r, bend left=20, hook, start anchor=10, end anchor=170] \arrow[r, phantom, "\bot"] & {{\mathord{\mathcal{V}}}}\text{-}\mathcal{C}at \arrow[l, bend left=20, start anchor=190, end anchor=-10, "(-)_0"]
\end{tikzcd}
\end{center}
\end{corollary}

n30778.content:
\begin{lemma}\label{lem:enriched-cob-adjunction}
  \uses{prop:change-of-base-adjunction}
Any adjunction comprised of finite-product-preserving functors between cartesian closed categories
\begin{center}
\begin{tikzcd}[column sep=large]
{\mathord{\mathcal{V}}}\arrow[r, bend left=20, "F"] \arrow[r, phantom, "\bot"] & {\mathord{\mathcal{W}}}\arrow[l, bend left=20, "U"]  \arrow[r, phantom, "\rightsquigarrow"] & {\mathord{\mathcal{V}}}\arrow[r, bend left=20, start anchor=20, end anchor=170, "F"] \arrow[r, phantom, "\bot"] & U_*{\mathord{\mathcal{W}}}\arrow[l, bend left=20, start anchor=190, end anchor=-15, "U"]  \end{tikzcd}
\end{center}
defines a ${\mathord{\mathcal{V}}}$-enriched adjunction between the ${\mathord{\mathcal{V}}}$-categories ${\mathord{\mathcal{V}}}$ and $U_*{\mathord{\mathcal{W}}}$; i.e., there exists a ${\mathord{\mathcal{V}}}$-natural isomorphism $U{\mathord{\mathcal{W}}}(Fv,w) \cong {\mathord{\mathcal{V}}}(v,Uw)$.
\end{lemma}

n30779.content:
\begin{proof}
The internal action $U_{a,b} \colon U{\mathord{\mathcal{W}}}(a,b) \to {\mathord{\mathcal{V}}}(Ua,Ub)$ of the ${\mathord{\mathcal{V}}}$-functor $U \colon U_*{\mathord{\mathcal{W}}}\to {\mathord{\mathcal{V}}}$ is defined by the transpose of the map $U\textup{ev}\colon U{\mathord{\mathcal{W}}}(a,b) \times Ua \to Ub$ defined by applying $U$ to the counit of the cartesian closure adjunction of ${\mathord{\mathcal{W}}}$. The ${\mathord{\mathcal{V}}}$-functoriality of this map follows from naturality of evaluation in a cartesian closed category.
%\eqref{eq:ev-ev-square}


By the ${\mathord{\mathcal{V}}}$-functoriality of $U \colon U_*{\mathord{\mathcal{W}}}\to {\mathord{\mathcal{V}}}$, the map
\begin{center}
\begin{tikzcd} U{\mathord{\mathcal{W}}}(Fv,w) \arrow[r, "U_{Fv,w}"] & {\mathord{\mathcal{V}}}(UFv,Uw) \arrow[r, "{- \circ \eta_v}"] & {\mathord{\mathcal{V}}}(v,Uw)
\end{tikzcd}
\end{center}
is ${\mathord{\mathcal{V}}}$-natural in $w \in U_*{\mathord{\mathcal{W}}}$ for all $v \in {\mathord{\mathcal{V}}}$. By a general result about enriching adjoints,  % Remark \ref{rmk:enriching-adjoints},
to construct a compatible ${\mathord{\mathcal{V}}}$-enrichment of $F$, we need only demonstrate that this map in an isomorphism in ${\mathord{\mathcal{V}}}$.

We do this by constructing an explicit inverse, namely
\begin{center}
\begin{tikzcd}
{\mathord{\mathcal{V}}}(v,Uw) \arrow[r, "\eta"] & UF{\mathord{\mathcal{V}}}(v,Uw) \arrow[r, "U(F_{v,Uw})"] & U{\mathord{\mathcal{W}}}(Fv,FUw) \arrow[r, "\epsilon_w \circ -"] & U{\mathord{\mathcal{W}}}(Fv,w)
\end{tikzcd}
\end{center}
where the middle map is defined by applying the unenriched functor $U$ to the action map from the ${\mathord{\mathcal{W}}}$-functor $F \colon F_*{\mathord{\mathcal{V}}}\to {\mathord{\mathcal{W}}}$, which is defined similarly to the ${\mathord{\mathcal{V}}}$-functor $U \colon U_*{\mathord{\mathcal{W}}}\to {\mathord{\mathcal{V}}}$.

The proof that these maps are inverses involves a pair of diagram chases, the first of which demonstrates that the top-right composite reduces to the left-bottom composite, which is the identity:
\begin{center}
\begin{tikzcd}
{\mathord{\mathcal{V}}}(v,Uw) \arrow[r, "\eta"] \arrow[ddrr, "\eta_{Uw}\circ-"'] & UF{\mathord{\mathcal{V}}}(v,Uw) \arrow[r, "U(F_{v,Uw})"] \arrow[dr, "UF_{v, Uw}" description] & U{\mathord{\mathcal{W}}}(Fv,FUw) \arrow[r, "\epsilon_w \circ -"] \arrow[d, "U_{Fv,FUw}"] & U{\mathord{\mathcal{W}}}(Fv,w) \arrow[d, "U_{Fv,w}"] \\ & & {\mathord{\mathcal{V}}}(UFv,UFUw) \arrow[r, "U\epsilon_w \circ -"]  \arrow[d, "-\circ \eta_v"]& {\mathord{\mathcal{V}}}(UFv,Uw) \arrow[d, "-\circ \eta_v"] \\ & & {\mathord{\mathcal{V}}}(v,UFUw) \arrow[r, "U\epsilon_w\circ-"] & {\mathord{\mathcal{V}}}(v,Uw)
\end{tikzcd}
\end{center}
The only subtle point is the commutativity of the trapezoidal region, which expresses the fact that $\eta \colon \textup{id}_{\mathord{\mathcal{V}}}\Rightarrow UF$ is a \emph{closed natural transformation} between product-preserving functors between cartesian closed categories. This region commutes because the transposed diagram does:
\begin{center}
\begin{tikzcd} {\mathord{\mathcal{V}}}(v,Uw) \times v\arrow[d, "\eta \times \eta_v"'] \arrow[r, equals] &  {\mathord{\mathcal{V}}}(v,Uw) \times v \arrow[d, "\eta"']  \arrow[r, "\textup{ev}"] & Uw \arrow[d, "\eta_{Uw}"] \\  UF{\mathord{\mathcal{V}}}(v,Uw)\times UFv  \arrow[r, "\cong"] & UF({\mathord{\mathcal{V}}}(v,UW)\times v) \arrow[r, "UF\textup{ev}"] & UFUw
\end{tikzcd}
\end{center}
the right-hand square by naturality, and the left-hand square because any naturally transformation between product-preserving functors is automatically a monoidal natural transformation. % (see Exercise \ref{exc:product-preservation-is-monoidal}).
  The other diagram chase is similar.
\end{proof}

