n30782.content:
\begin{lemma}\label{lem:pro-normal-monoidal} The change-of-base 2-functor induced by a finite-product-preserving functor $T \colon {\mathord{\mathcal{V}}}\to {\mathord{\mathcal{W}}}$ between cartesian closed categories preserves underlying categories, if and only if, for each $v \in {\mathord{\mathcal{V}}}$ the composite function on hom-sets
\begin{center}
\begin{tikzcd} {\mathord{\mathcal{V}}}(1,v)_0 \arrow[r, "T"] & {\mathord{\mathcal{W}}}(T1,Tv)_0 \arrow[r, "- \circ \cong"] & {\mathord{\mathcal{W}}}(1,Tv)_0
\end{tikzcd}
\end{center} is a bijection.
\end{lemma}

n30783.content:
\begin{proof}
The displayed function defines the component at $v \in {\mathord{\mathcal{V}}}$ of the unique monoidal natural transformation from the underlying set-functor for ${\mathord{\mathcal{V}}}$ to the composite of $T$ with the underlying set functor for ${\mathord{\mathcal{W}}}$. By the 2-functoriality of Remark \ref{rmk:change-of-base-2-fun}, if it defines a monoidal natural isomorphism, then it induces a 2-natural isomorphism between the underlying category 2-functor $(-)_0 \colon {{\mathord{\mathcal{V}}}}\text{-}{\mathord{\mathcal{Cat}}} \to {\mathord{\mathcal{Cat}}}$ and the composite of the change-of-base 2-functor $T_* \colon {{\mathord{\mathcal{V}}}}\text{-}{\mathord{\mathcal{Cat}}} \to{{\mathord{\mathcal{W}}}}\text{-}{\mathord{\mathcal{Cat}}}$ with the underlying category 2-functor $(-)_0 \colon {{\mathord{\mathcal{W}}}}\text{-}{\mathord{\mathcal{Cat}}} \to {\mathord{\mathcal{Cat}}}$.

Conversely, this condition is necessary for the underlying category of the ${\mathord{\mathcal{W}}}$-category $T_*{\mathord{\mathcal{V}}}$ to coincide with the underlying category of the cartesian closed category ${\mathord{\mathcal{V}}}$.
\end{proof}

n30784.content:
\begin{lemma}\label{lem:right-of-monoidal-adj-ucats}
  \uses{prop:change-of-base-adjunction} Consider a finite-product-preserving adjunction between cartesian closed categories:
\begin{center}
\begin{tikzcd}[column sep=large]
{\mathord{\mathcal{V}}}\arrow[r, bend left=20, "F"] \arrow[r, phantom, "\bot"] & {\mathord{\mathcal{W}}}\arrow[l, bend left=20, "U"]   \end{tikzcd}
\end{center}
Then change of base along the right adjoint respects the underlying categories:
\begin{center}
\begin{tikzcd}[sep=1.5 em] {{\mathord{\mathcal{W}}}}\text{-}\mathcal{C}at \arrow[rr, "U_*"] \arrow[dr, "{(-)_0}"'] & & {{\mathord{\mathcal{V}}}}\text{-}\mathcal{C}at \arrow[dl, "(-)_0"] \\ & \mathcal{C}at
\end{tikzcd}
\end{center}
\end{lemma}

n30785.content:
\begin{proof}
Let ${\mathord{\mathcal{C}}}$ be a ${\mathord{\mathcal{W}}}$ category. Then the hom-set in the underlying category of $U_*{\mathord{\mathcal{C}}}$ from $x$ to $y$ is isomorphic to the corresponding hom-set
\[ U_*{\mathord{\mathcal{C}}}(x,y)_0 \cong {\mathord{\mathcal{V}}}(1, U{\mathord{\mathcal{C}}}(x,y))_0 \cong {\mathord{\mathcal{W}}}(F1,{\mathord{\mathcal{C}}}(x,y))_0 \cong {\mathord{\mathcal{W}}}(1,{\mathord{\mathcal{C}}}(x,y))_0 \cong {\mathord{\mathcal{C}}}(x,y)_0\]
in the underlying category of ${\mathord{\mathcal{C}}}$ and moreover this isomorphism respects the composition and identities in the underlying categories. Thus ${\mathord{\mathcal{C}}}_0 \cong U{\mathord{\mathcal{C}}}_0$. A similar argument shows that change of base along $U$ respects underlying functors and natural transformations.
\end{proof}

