n30787.content:
\begin{proposition}[the $\infty$-cosmos of quasi-categories]\label{prop:qcat-cosmos}
  \uses{defn:cosmos, defn:quasi-category, defn:equivalence, defn:trivial-fibration, defn:qcat-equivalence, defn:qcat-trivial-fibration}
  The full subcategory ${\mathord{\mathcal{QCat}}}\subset{\mathord{\mathcal{sSet}}}$ of quasi-categories defines an $\infty$-cosmos in which the isofibrations, equivalences, and trivial fibrations coincide with the classes  already bearing these names.
\end{proposition}

n30788.content:
\begin{proof}
\uses{defn:qcat-isofibration} The proof requires myriad combinatorial results about the class of isofibrations between quasi-categories. See \cite[\S D]{RiehlVerity:2022eo}.
\end{proof}

n30789.content:
\begin{definition}[isofibrations of categories]\label{defn:cat-isofibration}
An \textbf{isofibration} between categories is a functor $f \colon A \fib B$ satisfying the displayed right lifting property for the inclusion of both endpoints of the free-living isomorphism:
\begin{center}
  \begin{tikzcd}
  {\Bbbone}\arrow[d, hook] \arrow[r] & A \arrow[d, "f", two heads] \\ {\BbbI}\arrow[r] \arrow[ur, dashed] & B
  \end{tikzcd}
  \end{center}
\end{definition}

n30790.content:
\begin{proposition}[the $\infty$-cosmos of categories]\label{prop:cat-cosmos}
\uses{defn:cosmos, defn:equivalence, defn:trivial-fibration, defn:cat-isofibration}
 The category ${\mathord{\mathcal{Cat}}}$ of 1-cat\-e\-go\-ri\-es defines an $\infty$-cosmos whose isofibrations are the isofibrations.
The equivalences are the equivalences of categories and the trivial fibrations are \textbf{surjective equivalences}: equivalences of categories that are also surjective on objects.
\end{proposition}

n30792.content:
\begin{proposition}[the $\infty$-cosmos of Kan complexes]\label{prop:kan-cosmos}
  \uses{defn:cosmos, defn:kan-complex, defn:equivalence, defn:trivial-fibration} The category ${\mathord{\mathcal{Kan}}}$ of Kan complexes defines an $\infty$-cosmos whose isofibrations are the \textbf{Kan fibrations}: maps that lift against all horn inclusions $\Lambda^k[n] \hookrightarrow\Delta[n]$ for $n \geq 1$ and $0 \leq k \leq n$.
\end{proposition}

n30793.content:
\begin{proposition}[sliced $\infty$-cosmoi]\label{prop:sliced-cosmoi} \uses{defn:cosmos}
  For any $\infty$-cosmos ${\mathord{\mathcal{K}}}$ and any $\infty$-cat\-e\-gory $B \in {\mathord{\mathcal{K}}}$ there is an \textbf{$\infty$-cosmos ${\mathord{\mathcal{K}}}_{/B}$ of isofibrations over $B$} whose
\begin{enumerate}
\item\label{itm:sliced-objects} objects are isofibrations $p \colon E \fib B$ with codomain $B$
\item\label{itm:sliced-functor-space} functor spaces, say from $p \colon E \fib B$ to $q \colon F \fib B$, are defined by pullback
\begin{center}
\begin{tikzcd}[column sep=small] {\mathord{\mathsf{Fun}}}_B(p \colon E \fib B,q\colon F\fib B) \arrow[r] \arrow[d, two heads] \arrow[dr, phantom, "\lrcorner" very near start] & {\mathord{\mathsf{Fun}}}(E,F) \arrow[d, two heads, "{q_*}"] \\ {\Bbbone}\arrow[r, "p"] & {\mathord{\mathsf{Fun}}}(E,B)
\end{tikzcd}
\end{center}
and abbreviated to ${\mathord{\mathsf{Fun}}}_B(E,F)$ when the specified isofibrations are clear from context
\item\label{itm:sliced-isofibrations} isofibrations are commutative triangles of isofibrations over $B$
\begin{center}
\begin{tikzcd}[row sep=small, column sep=small]
E \arrow[rr,two heads, "r"] \arrow[dr, two heads, "p"'] & & F \arrow[dl, two heads, "q"] \\ & B
\end{tikzcd}
\end{center}
\item\label{itm:sliced-products} terminal object is $\textup{id}\colon B \fib B$ and products are defined by the pullback along the diagonal
\begin{center}
\begin{tikzcd} \times^B_i E_i \arrow[r] \arrow[d, two heads] \arrow[dr, phantom, "\lrcorner" very near start] & \prod_i E_i \arrow[d, two heads, "\prod_i p_i"] \\ B \arrow[r, "\Delta"] & \prod_i B
\end{tikzcd}
\end{center}
\item\label{itm:sliced-pullbacks} pullbacks and limits of towers of isofibrations are created by the forgetful functor ${\mathord{\mathcal{K}}}_{/B} \to {\mathord{\mathcal{K}}}$
\item\label{itm:sliced-cotensors} simplicial cotensor of $p \colon E \fib B$ with $U \in {\mathord{\mathcal{sSet}}}$ is constructed by the pullback
\begin{center}
\begin{tikzcd} U \div_B p \arrow[d, two heads] \arrow[r] \arrow[dr, phantom, "\lrcorner" very near start] & E^U \arrow[d, two heads, "p^U"] \\ B \arrow[r, "\Delta"] & B^U
\end{tikzcd}
\end{center}
\item\label{itm:fibered-equivalence} and in which a map over $B$
\begin{center}
\begin{tikzcd}[row sep=small, column sep=small]
E \arrow[rr, "f"] \arrow[dr, two heads, "p"'] & & F \arrow[dl, two heads, "q"] \\ & B
\end{tikzcd}
\end{center}
is an equivalence in the $\infty$-cosmos ${\mathord{\mathcal{K}}}_{/B}$ if and only if $f$ is an equivalence in ${\mathord{\mathcal{K}}}$.
\end{enumerate}
\end{proposition}

n30794.content:
\begin{proof}
  \uses{lem:trivial-fib-conical, lem:brown-fact}
The functor spaces are quasi-categories since axiom \ref{defn:cosmos}\ref{itm:cosmos-isofib} asserts that for any isofibration $q \colon F \fib B$ in ${\mathord{\mathcal{K}}}$ the map $q_* \colon {\mathord{\mathsf{Fun}}}(E,F) \fib {\mathord{\mathsf{Fun}}}(E,B)$ is an isofibration of quasi-categories. Other parts of this axiom imply that each of the limit constructions --- such as the products and cotensors constructed in \ref{itm:sliced-products} and \ref{itm:sliced-cotensors} --- define isofibrations over $B$. The closure properties of the isofibrations in ${\mathord{\mathcal{K}}}_{/B}$ follow from the corresponding ones in ${\mathord{\mathcal{K}}}$. The most complicated of these is the Leibniz cotensor stability of the isofibrations in ${\mathord{\mathcal{K}}}_{/B}$, which follows from the corresponding property in ${\mathord{\mathcal{K}}}$, since for a monomorphism of simplicial sets $i \colon X\hookrightarrow Y$ and an isofibration $r$ over $B$ as in \ref{itm:sliced-isofibrations} above, the map $i \mathbin{\widehat{\div_B}} r$ is constructed by pulling back $\widehat{\{i , r\}}$ along $\Delta \colon B \to B^Y$.

The fact that the above constructions define simplicially enriched limits in a simplicially enriched slice category are standard from enriched category theory. It remains only to verify that the equivalences in the $\infty$-cosmos of isofibrations are created by the forgetful functor ${\mathord{\mathcal{K}}}_{/B} \to {\mathord{\mathcal{K}}}$. Suppose first that the map $f$ displayed in \ref{itm:fibered-equivalence} defines an equivalence in ${\mathord{\mathcal{K}}}$. Then for any isofibration $s \colon A \fib B$ the induced map on functor spaces in ${\mathord{\mathcal{K}}}_{/B}$ is defined by the pullback:
\begin{center}
\begin{tikzcd}
{\mathord{\mathsf{Fun}}}_B(A,E) \arrow[dr, "{f_*}", dashed, "\sim"'] \arrow[dd, two heads] \arrow[ddr, phantom, "\lrcorner" pos=.001] \arrow[rr] & & {\mathord{\mathsf{Fun}}}(A,E) \arrow[dd, two heads, "{p_*}"' near start] \arrow[dr, "{f_*}", "\sim"'] \\ & {\mathord{\mathsf{Fun}}}_B(A,F) \arrow[dl, two heads] \arrow[dr, phantom, "\lrcorner" very near start] \arrow[rr, crossing over] & & {\mathord{\mathsf{Fun}}}(A,F) \arrow[dl, two heads, "{q_*}"] \\ {\Bbbone}\arrow[rr, "s"'] & ~& {\mathord{\mathsf{Fun}}}(A,B)
\end{tikzcd}
\end{center}
Since $f$ is an equivalence in ${\mathord{\mathcal{K}}}$, the map $f_* \colon {\mathord{\mathsf{Fun}}}(A,E) \to {\mathord{\mathsf{Fun}}}(A,F)$ is an equivalence, and so it follows that the induced map on fibers over $s$ is an equivalence as well.\footnote{The stability of equivalences between isofibrations under pullback can be proven either as a consequence of Lemmas \ref{lem:trivial-fib-conical} and \ref{lem:brown-fact} using standard techniques from simplicial homotopy theory %(see Lemma \ref{lem:pullback-of-fibered-equiv})
 or by arguing 2-categorically.} %(see Proposition \ref{prop:dual-gluing-lemma}).}

For the converse implication, we appeal to  Lemma \ref{lem:equiv-htpy-equiv}. If $f \colon E \to F$ is an equivalence in ${\mathord{\mathcal{K}}}_{/B}$ then it admits a homotopy inverse in ${\mathord{\mathcal{K}}}_{/B}$. The inverse equivalence $g \colon F \to E$ also defines an inverse equivalence in ${\mathord{\mathcal{K}}}$ and the required simplicial homotopies in ${\mathord{\mathcal{K}}}$
\begin{center}
\begin{tikzcd}
E \arrow[r, "\alpha"] & {\BbbI}\div_Bp \arrow[r] & E^{\BbbI}& F \arrow[r, "\beta"] & {\BbbI}\div_Bq \to F^{\BbbI}\end{tikzcd}
\end{center}
are defined by composing with the top horizontal leg of the pullback defining the cotensor in ${\mathord{\mathcal{K}}}_{/B}$.
\end{proof}

n30795.content:
\begin{definition}[cartesian closed $\infty$-cosmoi]\label{defn:closed-cosmos}
  \uses{defn:cosmos} An $\infty$-cosmos ${\mathord{\mathcal{K}}}$ is \textbf{cartesian closed} if the product bifunctor
$- \times -\colon {\mathord{\mathcal{K}}}\times {\mathord{\mathcal{K}}}\to {\mathord{\mathcal{K}}}$ extends to a simplicially enriched two-variable adjunction
\[ {\mathord{\mathsf{Fun}}}(A \times B,C) \cong {\mathord{\mathsf{Fun}}}(A,C^B) \cong {\mathord{\mathsf{Fun}}}(B,C^A)\]
in which the right adjoints $(-)^A \colon {\mathord{\mathcal{K}}}\to {\mathord{\mathcal{K}}}$ preserve isofibrations for all $A \in {\mathord{\mathcal{K}}}$.
\end{definition}

n30797.content:
\begin{definition}[homotopy 2-category]\label{defn:homotopy-2-cat}
  \uses{defn:cosmos, defn:homotopy-cat, ex:nerve-ho-change-of-base, prop:2-cat-as-cat-enriched} Let ${\mathord{\mathcal{K}}}$ be an $\infty$-cosmos. Its \textbf{homotopy 2-category} is the 2-category $\mathfrak{h}{\mathord{\mathcal{K}}}$ whose
\begin{itemize}
\item objects are the objects $A, B$ of ${\mathord{\mathcal{K}}}$, i.e., the $\infty$-categories;\item 1-cells $f \colon A \to B$ are the 0-arrows in the functor space ${\mathord{\mathsf{Fun}}}(A,B)$, i.e., the $\infty$-functors; and
\item 2-cells
\begin{center}
\begin{tikzcd} A \arrow[r, start anchor=15, end anchor=165, bend left, "f"] \arrow[r, start anchor=345, end anchor=195, bend right, "g"'] \arrow[r, phantom, "{\scriptstyle\Downarrow \alpha}"] & B\end{tikzcd}
\end{center}
 are homotopy classes of 1-simplices in ${\mathord{\mathsf{Fun}}}(A,B)$, which we call \textbf{$\infty$-natural transformations}.
\end{itemize}
Put another way $\mathfrak{h}{\mathord{\mathcal{K}}}$ is the 2-category with the same objects as ${\mathord{\mathcal{K}}}$ and with hom-categories defined by
\[ {\mathord{\mathsf{hFun}}}(A,B)   \coloneq {\mathord{\mathsf{h}}}({\mathord{\mathsf{Fun}}}(A,B)),\]
that is, ${\mathord{\mathsf{hFun}}}(A,B)$ is the homotopy category of the quasi-category ${\mathord{\mathsf{Fun}}}(A,B)$.
\end{definition}

n30798.content:
\begin{definition}[underlying category of a 2-category]\label{defn:underlying-cat-of-2cat}
The \textbf{underlying category} of a 2-category is defined by simply forgetting its 2-cells. Note that an $\infty$-cosmos ${\mathord{\mathcal{K}}}$ and its homotopy 2-category $\mathfrak{h}{\mathord{\mathcal{K}}}$ share the same underlying category ${\mathord{\mathcal{K}}}_0$ of $\infty$-categories and $\infty$-functors in ${\mathord{\mathcal{K}}}$.
\end{definition}

n30799.content:
\begin{lemma}\label{lem:underlying-cat-iso}
  \uses{defn:underlying-cat-of-2cat, defn:underlying-cat, defn:homotopy-2-cat}
  The underlying category of the homotopy 2-category of an $\infty$-cosmos is isomorphic to the underlying category of the $\infty$-cosmos.
\end{lemma}

n30800.content:
\begin{lemma}\label{lem:invertible-2-cell}$\quad$
  \uses{defn:homotopy-2-cat, lem:qcat-1-simplex-htpy, prop:coherent-iso}
  \begin{enumerate}
  \item\label{itm:2-cell-as-functor} Every 2-cell
  \begin{center}
  \begin{tikzcd} A \arrow[r, start anchor=15, end anchor=165, bend left, "f"] \arrow[r, start anchor=345, end anchor=195, bend right, "g"'] \arrow[r, phantom, "\scriptstyle\Downarrow\alpha"] & B \end{tikzcd}
  \end{center}  in the homotopy 2-category of an $\infty$-cosmos is represented by a map of quasi-categories as below-left or equivalently by a functor as below-right
  \begin{center}
  \begin{tikzcd}[sep=small] & {\Bbbone}+{\Bbbone}\arrow[dl, hook'] \arrow[dr, "{(f,g)}"] & &  & ~ &  A \arrow[rr, "{\ulcorner{\alpha}\urcorner}"] \arrow[dr, "{(g,f)}"'] & & B^{\Bbbtwo}\arrow[dl, "{(p_1,p_0)}", two heads] \\ {\Bbbtwo}\arrow[rr, "{\alpha}"'] && {\mathord{\mathsf{Fun}}}(A,B) &\arrow[ur, phantom, "\leftrightsquigarrow"] &  && B \times B
  \end{tikzcd}
  \end{center}
  and two such maps represent the same 2-cell if and only if they are homotopic as 1-simplices in ${\mathord{\mathsf{Fun}}}(A,B)$.
  \item\label{itm:2-iso-as-functor} Every invertible 2-cell
  \begin{center}
  \begin{tikzcd}[column sep=large] A \arrow[r, start anchor=18, end anchor=162, bend left=20, "f"] \arrow[r,  start anchor=342, end anchor=198, bend right=20, "g"'] \arrow[r, phantom, "\scriptstyle\cong\Downarrow\alpha"] & B \end{tikzcd}
  \end{center}
  in the homotopy 2-category of an $\infty$-cosmos is represented by a map of quasi-categories  as below-left or equivalently by a functor as below-right
  \begin{center}
  \begin{tikzcd}[sep=small] & {\Bbbone}+{\Bbbone}\arrow[dl, hook'] \arrow[dr, "{(f,g)}"] & &  & ~ &  A \arrow[rr, "{\ulcorner{\alpha}\urcorner}"] \arrow[dr, "{(g,f)}"'] & & B^{\BbbI}\arrow[dl, "{(p_1,p_0)}", two heads] \\ {\BbbI}\arrow[rr, "{\alpha}"'] && {\mathord{\mathsf{Fun}}}(A,B) &\arrow[ur, phantom, "\leftrightsquigarrow"] &  && B \times B
  \end{tikzcd}
  \end{center} and two such maps represent the same invertible 2-cell if and only if their common restrictions along ${\Bbbtwo}\hookrightarrow{\BbbI}$ are homotopic as 1-simplices in ${\mathord{\mathsf{Fun}}}(A,B)$.
  \end{enumerate}
  \end{lemma}

n30802.content:
\begin{proposition}[cartesian (closure)]\label{prop:htpy-2-cat-closure}
    \uses{defn:cosmos, defn:closed-cosmos}
  $\quad$
  \begin{enumerate}
  \item The homotopy 2-category of any $\infty$-cosmos has 2-categorical products.
  \item\label{itm:cart-closed} The homotopy 2-category of a cartesian closed $\infty$-cosmos is cartesian closed as a 2-category.
  \end{enumerate}
  \end{proposition}

n30803.content:
\begin{proof}
    \uses{lem:ho-preserves-finite-products}
  While the functor ${\mathord{\mathsf{h}}}\colon{\mathord{\mathcal{sSet}}}\to {\mathord{\mathcal{Cat}}}$ only preserves finite products, the restricted functor ${\mathord{\mathsf{h}}}\colon{\mathord{\mathcal{QCat}}}\to{\mathord{\mathcal{Cat}}}$ preserves \emph{all} products on account of the simplified description of the homotopy category of a quasi-category given in Lemma \ref{lem:htpy-cat-of-qcat}. Thus for any set $I$ and family of $\infty$-categories $(A_i)_{i \in I}$ in ${\mathord{\mathcal{K}}}$, the homotopy category functor carries the isomorphism of functor spaces  to an isomorphism of hom-categories
  \begin{center} \begin{tikzcd}[column sep=small] {\mathord{\mathsf{Fun}}}(X,\prod_{i \in I} A_i) \arrow[r, "\cong"] & \prod_{i \in I} {\mathord{\mathsf{Fun}}}(X,A_i) & \arrow[r, maps to, "{\mathord{\mathsf{h}}}"] & ~ & {\mathord{\mathsf{hFun}}}(X,\prod_{i \in I} A_i) \arrow[r, "\cong"] & \prod_{i \in I} {\mathord{\mathsf{hFun}}}(X,A_i).
  \end{tikzcd}
  \end{center}
  This proves that the homotopy 2-category $\mathfrak{h}{\mathord{\mathcal{K}}}$ has products whose universal properties have both a 1- and 2-dimensional component, as described in the empty case for terminal objects above.

  If ${\mathord{\mathcal{K}}}$ is a cartesian closed $\infty$-cosmos, then for any triple of $\infty$-categories $A,B,C \in {\mathord{\mathcal{K}}}$ there exist exponential objects $C^A, C^B \in {\mathord{\mathcal{K}}}$ characterized by natural isomorphisms
  \[ {\mathord{\mathsf{Fun}}}(A \times B, C) \cong {\mathord{\mathsf{Fun}}}(A, C^B) \cong {\mathord{\mathsf{Fun}}}(B,C^A).\] Passing to homotopy categories we have natural isomorphisms
  \[ {\mathord{\mathsf{hFun}}}(A \times B, C) \cong {\mathord{\mathsf{hFun}}}(A, C^B) \cong {\mathord{\mathsf{hFun}}}(B,C^A),\] which demonstrates that $\mathfrak{h}{\mathord{\mathcal{K}}}$ is cartesian closed as a 2-category: functors $A \times B \to C$ transpose to define functors $A \to C^B$ and $B \to C^A$, and natural transformations transpose similarly.
  \end{proof}

n30804.content:
\begin{definition}[equivalence]\label{defn:2-cat-equivalence} An \textbf{equivalence} in a 2-category is given by
  \begin{itemize}
  \item a pair of objects $A$ and $B$;
  \item a pair of 1-cells $f \colon A \to B$ and $g \colon B \to A$; and
  \item a pair of invertible 2-cells
  \begin{center}
  \begin{tikzcd}[column sep=large]
  A \arrow[r, bend left=25, equals] \arrow[r, bend right=25, "gf"'] \arrow[r, phantom, "{\scriptstyle\cong\Downarrow\alpha}"] & A & \text{and} & B \arrow[r, bend right=25, equals] \arrow[r, bend left=25, "fg"] \arrow[r, phantom, "{\scriptstyle\cong\Downarrow\beta}"] & B
  \end{tikzcd}
  \end{center}
  \end{itemize}
  When $A$ and $B$ are \textbf{equivalent}, we write $A \simeq B$ and refer to the 1-cells $f$ and $g$ as \textbf{equivalences}, denoted by ``$\xrightarrow{{\smash{\mathlower{0.8}{\sim}}}}$.''
  \end{definition}

n30805.content:
\begin{theorem}[equivalences are equivalences]\label{thm:equiv-are-equiv}
    \uses{defn:cosmos, defn:equivalence, defn:2-cat-equivalence, defn:homotopy-2-cat} In any $\infty$-cosmos ${\mathord{\mathcal{K}}}$, the following are equivalent and characterize what it means for a functor $f \colon A \to B$ between $\infty$-categories to define an \textbf{equivalence}.
  \begin{enumerate}
  \item\label{itm:rep-equiv} For all $X \in {\mathord{\mathcal{K}}}$, the post-composition map $f_* \colon {\mathord{\mathsf{Fun}}}(X,A) \xrightarrow{{\smash{\mathlower{0.8}{\sim}}}}{\mathord{\mathsf{Fun}}}(X,B)$ defines an equivalence of quasi-categories.
  \item\label{itm:2cat-equiv} There exists a functor $g \colon B \to A$ and natural isomorphisms $\alpha \colon \textup{id}_A \cong gf$ and $\beta \colon fg \cong \textup{id}_B$ in the homotopy 2-category.
  \item\label{itm:htpy-equiv} There exists a functor $g \colon B \to A$ and maps
  \begin{center}
  \begin{tikzcd} & A & &  & B \\ A \arrow[ur, equals] \arrow[dr, "gf"'] \arrow[r, "\alpha"] & A^{\BbbI}\arrow[u, two heads, "\sim", "\textup{ev}_0"'] \arrow[d, two heads, "\sim"', "\textup{ev}_1"] &\text{and} &  B \arrow[dr, equals] \arrow[r, "\beta"] \arrow[ur, "fg"] & B^{\BbbI}\arrow[u, two heads, "\sim", "\textup{ev}_0"'] \arrow[d, two heads, "\sim"', "\textup{ev}_1"] \\ & A & &  & B
  \end{tikzcd}
  \end{center} in the $\infty$-cosmos ${\mathord{\mathcal{K}}}$.
  \end{enumerate}
  \end{theorem}

n30806.content:
\begin{proof}
    For \ref{itm:rep-equiv}$\Rightarrow$\ref{itm:2cat-equiv}, if the induced map $f_* \colon {\mathord{\mathsf{Fun}}}(X,A) \xrightarrow{{\smash{\mathlower{0.8}{\sim}}}}{\mathord{\mathsf{Fun}}}(X,B)$  defines an equivalence of quasi-categories then the functor $f_* \colon {\mathord{\mathsf{hFun}}}(X,A) \xrightarrow{{\smash{\mathlower{0.8}{\sim}}}}{\mathord{\mathsf{hFun}}}(X,B)$ defines an equivalence of categories, by Lemma \ref{lem:qcat-htpy-cat-equiv}. In particular, the equivalence $f_* \colon {\mathord{\mathsf{hFun}}}(B,A) \xrightarrow{{\smash{\mathlower{0.8}{\sim}}}}{\mathord{\mathsf{hFun}}}(B,B)$ is essentially surjective so there exists $g \in {\mathord{\mathsf{hFun}}}(B,A)$ and an isomorphism $\beta \colon fg \cong \textup{id}_B \in {\mathord{\mathsf{hFun}}}(B,B)$. Now since $f_* \colon {\mathord{\mathsf{hFun}}}(A,A) \xrightarrow{{\smash{\mathlower{0.8}{\sim}}}}{\mathord{\mathsf{hFun}}}(A,B)$ is fully faithful, the isomorphism $\beta f \colon fgf \cong f \in {\mathord{\mathsf{hFun}}}(A,B)$ can be lifted to define an isomorphism $\alpha^{-1} \colon gf \cong \textup{id}_A \in {\mathord{\mathsf{hFun}}}(A,A)$. This defines the data of a 2-categorical equivalence in Definition \ref{defn:2-cat-equivalence}.

  To see that \ref{itm:2cat-equiv}$\Rightarrow$\ref{itm:htpy-equiv} recall from Lemma \ref{lem:invertible-2-cell} that the natural isomorphisms $\alpha \colon \textup{id}_A \cong gf$ and $\beta \colon fg \cong \textup{id}_B$ in $\mathfrak{h}{\mathord{\mathcal{K}}}$ are represented by maps $\alpha \colon A \to A^{\BbbI}$ and $\beta \colon B \to B^{\BbbI}$ in ${\mathord{\mathcal{K}}}$ as in Lemma \ref{lem:equiv-htpy-equiv}.

  Finally, \ref{itm:htpy-equiv}$\Rightarrow$\ref{itm:rep-equiv} since ${\mathord{\mathsf{Fun}}}(X,-)$ carries the data of \ref{itm:htpy-equiv} to the data of an equivalence of quasi-categories as in  Definition \ref{defn:qcat-equivalence}.
  \end{proof}

n30807.content:
\begin{corollary}\label{cor:equiv-invar-fun}
    \uses{defn:cosmos} Equivalences of $\infty$-categories $A' \xrightarrow{{\smash{\mathlower{0.8}{\sim}}}}A$ and $B \xrightarrow{{\smash{\mathlower{0.8}{\sim}}}}B'$ induce an equivalence of functor spaces ${\mathord{\mathsf{Fun}}}(A,B) \xrightarrow{{\smash{\mathlower{0.8}{\sim}}}}{\mathord{\mathsf{Fun}}}(A',B')$.
  \end{corollary}

n30809.content:
\begin{proposition}[isofibrations are isofibrations]\label{prop:isofib-define-isofib}
    \uses{defn:cosmos} An isofibration $p \colon E \fib B$  in an $\infty$-cosmos ${\mathord{\mathcal{K}}}$ also defines an \textbf{isofibration} in the homotopy 2-category $\mathfrak{h}{\mathord{\mathcal{K}}}$: given any invertible 2-cell as displayed below-left abutting to $B$ with a specified lift of one of its boundary 1-cells through $p$, there exists an invertible 2-cell abutting to $E$ with this boundary 1-cell as displayed below-right that whiskers with $p$ to the original 2-cell.
  \begin{center}
    \begin{tikzcd} X \arrow[r, "e"] \arrow[dr, bend right, "b"'] & E \arrow[d, two heads, "p"] \arrow[dl, phantom, "{\scriptstyle\cong\Downarrow\beta}" near start] &\arrow[d, phantom, "="] & X \arrow[rr, start anchor=15, end anchor=165, bend left=20, "e"] \arrow[rr, start anchor=345, end anchor=195, bend right=20, "\bar{e}"', dashed] \arrow[rr, phantom, "{\scriptstyle\cong\Downarrow\gamma}"] && E \arrow[d, two heads, "p"] \\ ~ & B & ~ & & & B
  \end{tikzcd}
  \end{center}
  \end{proposition}

n30810.content:
\begin{proof} The universal property of the statement says that the functor \[p_* \colon {\mathord{\mathsf{hFun}}}(X,E) \fib {\mathord{\mathsf{hFun}}}(X,B)\] is an isofibration of categories in the sense defined in Proposition \ref{prop:cat-cosmos}. By axiom \ref{defn:cosmos}\ref{itm:cosmos-isofib}, since $p \colon E \fib B$ is an isofibration in ${\mathord{\mathcal{K}}}$, the induced map $p_* \colon {\mathord{\mathsf{Fun}}}(X,E) \fib {\mathord{\mathsf{Fun}}}(X,B)$ is an isofibration of quasi-categories. So it suffices to show that the functor ${\mathord{\mathsf{h}}}\colon {\mathord{\mathcal{QCat}}}\to {\mathord{\mathcal{Cat}}}$ carries isofibrations of quasi-categories to isofibrations of categories.

  So let us now consider an isofibration $p \colon E \fib B$ between quasi-categories. By Proposition \ref{prop:coherent-iso}, every isomorphism $\beta$ in the homotopy category ${\mathord{\mathsf{h}}}{B}$ of the quasi-category $B$ is represented by a simplicial map $\beta \colon {\BbbI}\to B$. By Definition \ref{defn:qcat-isofibration}, the lifting problem
  \begin{center}
  \begin{tikzcd}
  {\Bbbone}\arrow[r, "e"] \arrow[d, hook] & E \arrow[d, two heads, "p"] \\ {\BbbI}\arrow[ur, dashed, "\gamma"] \arrow[r, "\beta"'] & B
  \end{tikzcd}
  \end{center}
  can be solved, and the map $\gamma \colon {\BbbI}\to E$ so produced represents a lift of the isomorphism from ${\mathord{\mathsf{h}}}{B}$ to an isomorphism in ${\mathord{\mathsf{h}}}{E}$ with domain $e$.
  \end{proof}

n30811.content:
\begin{definition}[homotopy category of an $\infty$-category]\label{defn:htpy-cat-of-infinity-cat}
  \uses{defn:cosmos, defn:homotopy-cat}
    The \textbf{homotopy category} of an $\infty$-category $A$ in an $\infty$-cosmos ${\mathord{\mathcal{K}}}$ is defined to be the homotopy category of its underlying quasi-category, that is:
  \[ {\mathord{\mathsf{h}}}A \coloneq {\mathord{\mathsf{hFun}}}(1,A) \coloneq {\mathord{\mathsf{h}}}({\mathord{\mathsf{Fun}}}(1,A)).\]
  \end{definition}
